WITH valid AS (SELECT id, customer_id, store_id, order_date, channel, amount, discount, shipping_fee, discount + shipping_fee AS discount_plus_shipping_fee, COALESCE(channel, 'UNKNOWN') AS resolved_channel FROM orders WHERE status IN ('PENDING', 'CANCELLED') AND channel IS DISTINCT FROM 'web') SELECT id, customer_id, order_date, channel, discount, COUNT(discount) OVER w_part AS last4_count_discount, MAX(discount) OVER w_part AS last4_max_discount, MIN(discount) OVER w_part AS last4_min_discount FROM valid WINDOW w_part AS (PARTITION BY channel ORDER BY discount_plus_shipping_fee, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW);
